('How to use Antigravity AI for Developers', 'huong-dan-su-dung-ai-antigravity',
'A comprehensive guide on leveraging Antigravity to speed up your coding workflow.',
'<p>Antigravity là một trợ lý AI lập trình vô cùng mạnh mẽ, hoạt động như một Developer thực thụ bên cạnh bạn.</p><h3>1. Khởi chạy Antigravity</h3><p>Để bắt đầu, bạn cần cài đặt extention Antigravity trong VSCode. Giao diện cực kỳ trực quan giúp bạn giao tiếp bằng ngôn ngữ tự nhiên.</p><figure><img src="/images/antigravity_1.png" alt="Illustration 1" class="w-full h-auto object-cover rounded-xl shadow-md my-8" /></figure><h3>2. Yêu cầu sửa lỗi (Fix Bugs)</h3><p>Tính năng mạnh nhất của AI này là đọc Codebase gốc của bạn. Khi dự án lỗi, bạn chỉ cần gạch đầu dòng báo lỗi, AI sẽ tự dò tìm file và đề xuất mã fix.</p><figure><img src="/images/antigravity_2.png" alt="Illustration 2" class="w-full h-auto object-cover rounded-xl shadow-md my-8" /></figure><h3>3. Tự động hóa quá trình Deploy</h3><p>Nếu bạn không rành về GitHub Actions hay Vercel, hãy nhờ AI tạo ra các kịch bản <code>.yml</code> và cấu hình hệ thống máy chủ chỉ bằng 1 câu lệnh.</p><p>Chúc bạn code vui vẻ với Antigravity!</p>',
'HTML', '/images/openclaw_article.png', 'How to use Antigravity AI for Developers', 'PUBLISHED', NOW(),
'How to use Antigravity AI for Developers',
'A comprehensive guide on leveraging Antigravity to speed up your coding workflow.',
'vi-VN', 3, 600, 150, 4, true, true, 1, NOW(), NOW());

-- ============================================================
-- MAP CATEGORIES AND TAGS
-- ============================================================
INSERT INTO post_categories (post_id, category_id, is_primary, created_at)
SELECT p.id, c.id, true, NOW()
FROM posts p
CROSS JOIN categories c
WHERE p.slug IN (
  'openclaw-va-khoanh-khac-ai-vuot-qua-ranh-gioi-kiem-soat',
  'ai-trong-thoi-dai-it-lieu-co-con-can-hoc-lap-trinh',
  'ai-khien-viec-build-tro-nen-re-va-do-moi-la-van-de',
  'token-trong-ai-hieu-ve-tien-te-cua-tri-tue-nhan-tao',
  'huong-dan-su-dung-ai-antigravity'
) AND c.slug = 'tri-tue-nhan-tao';

INSERT INTO post_tags (post_id, tag_id, created_at)
SELECT p.id, t.id, NOW()
FROM posts p
CROSS JOIN tags t
WHERE p.slug IN (
  'openclaw-va-khoanh-khac-ai-vuot-qua-ranh-gioi-kiem-soat',
  'ai-trong-thoi-dai-it-lieu-co-con-can-hoc-lap-trinh',
  'ai-khien-viec-build-tro-nen-re-va-do-moi-la-van-de',
  'token-trong-ai-hieu-ve-tien-te-cua-tri-tue-nhan-tao',
  'huong-dan-su-dung-ai-antigravity'
) AND t.slug = 'ai';

INSERT INTO post_authors (post_id, user_id, role, sort_order)
SELECT id, 1, 'AUTHOR', 1 FROM posts WHERE slug IN (
  'openclaw-va-khoanh-khac-ai-vuot-qua-ranh-gioi-kiem-soat',
  'ai-trong-thoi-dai-it-lieu-co-con-can-hoc-lap-trinh',
  'ai-khien-viec-build-tro-nen-re-va-do-moi-la-van-de',
  'token-trong-ai-hieu-ve-tien-te-cua-tri-tue-nhan-tao',
  'huong-dan-su-dung-ai-antigravity'
);
